using Contoso.Services;

namespace Contoso.Services.Tests;

[TestClass]
public sealed class ServiceRegistryTests
{
    private readonly ServiceRegistry _registry = new();

    [TestMethod]
    public void Register_ThenResolve_ReturnsSameInstance()
    {
        var service = new DummyService();

        _registry.Register<IDummyService>(service);
        var resolved = _registry.Resolve<IDummyService>();

        Assert.AreSame(service, resolved);
    }

    [TestMethod]
    public void Resolve_Unregistered_ReturnsNull()
    {
        var resolved = _registry.Resolve<IDummyService>();

        Assert.IsNull(resolved);
    }

    [TestMethod]
    public void GetAll_ContainsRegisteredService_AndNotAfterRemoval()
    {
        var service = new DummyService();

        _registry.Register<IDummyService>(service);
        CollectionAssert.Contains(_registry.GetAll().ToList(), service);

        _registry.Remove<IDummyService>();
        CollectionAssert.DoesNotContain(_registry.GetAll().ToList(), service);
    }

    [TestMethod]
    public void GetAll_IsEmptyBeforeRegistration_AndNotEmptyAfter()
    {
        Assert.AreEqual(0, _registry.GetAll().Count);

        _registry.Register<IDummyService>(new DummyService());

        Assert.AreNotEqual(0, _registry.GetAll().Count);
    }

    private interface IDummyService;
    private sealed class DummyService : IDummyService;
}

